import AsyncStorage from '@react-native-async-storage/async-storage';
import * as Speech from 'expo-speech';
import { Platform } from 'react-native';

/** Natural voices generated by the server (OpenAI). They only play on the web for now. */
// Warm, bright voices only: the deep or flat ones scared younger children.
export const AI_VOICES = [
  { id: 'marin', label: 'Marina', hint: 'Mujer · la más natural, dulce y cercana' },
  { id: 'cedar', label: 'Cedro', hint: 'Hombre · el más natural, amable y tranquilo' },
  { id: 'coral', label: 'Coral', hint: 'Mujer · cálida y alegre' },
  { id: 'shimmer', label: 'Brillo', hint: 'Mujer · suave, de cuento' },
  { id: 'nova', label: 'Nova', hint: 'Mujer · animada y con energía' },
  { id: 'sage', label: 'Salvia', hint: 'Mujer · serena' },
  { id: 'ballad', label: 'Balada', hint: 'Hombre · dulce, de cuentacuentos' },
  { id: 'verse', label: 'Verso', hint: 'Hombre · expresivo y juguetón' },
] as const;

export type VoiceChoice = { kind: 'ai'; id: string } | { kind: 'device'; id: string } | { kind: 'auto' };
export const aiVoicesAvailable = Platform.OS === 'web';
export const VOICE_SAMPLE = '¡Hola! ¡Qué alegría verte! Soy tu tutor. ¿Aprendemos algo nuevo juntos?';

// v2: everyone starts again on the friendlier default voice.
const KEY = 'onekids.tutor-voice.v2';
// Natural voices by default on the web; the device's best Spanish voice elsewhere.
export const DEFAULT_VOICE: VoiceChoice = aiVoicesAvailable ? { kind: 'ai', id: 'marin' } : { kind: 'auto' };

export async function loadVoiceChoice(): Promise<VoiceChoice> {
  try {
    const parsed = JSON.parse((await AsyncStorage.getItem(KEY)) || 'null');
    if (parsed?.kind === 'auto') return parsed;
    if (parsed?.kind === 'ai' && aiVoicesAvailable && AI_VOICES.some(v => v.id === parsed.id)) return parsed;
    if (parsed?.kind === 'device' && typeof parsed.id === 'string') return parsed;
  } catch { /* fall back to the default voice */ }
  return DEFAULT_VOICE;
}
export async function saveVoiceChoice(choice: VoiceChoice) {
  try { await AsyncStorage.setItem(KEY, JSON.stringify(choice)); } catch { /* a convenience; never block the lesson */ }
}

/** Higher scores sound less robotic: enhanced/neural voices first, then Spain/Latin America defaults. */
function score(voice: Speech.Voice) {
  const name = `${voice.name} ${voice.identifier}`.toLowerCase();
  let total = voice.quality === Speech.VoiceQuality.Enhanced ? 50 : 0;
  if (/natural|neural|premium|enhanced|online/.test(name)) total += 40;
  if (/google/.test(name)) total += 25;
  if (/siri/.test(name)) total += 20;
  if (/compact|espeak/.test(name)) total -= 30;
  if (/^es-(es|mx|us|419)/i.test(voice.language)) total += 5;
  return total;
}

export async function deviceSpanishVoices(): Promise<Speech.Voice[]> {
  try {
    const voices = await Speech.getAvailableVoicesAsync();
    const seen = new Set<string>();
    return voices
      .filter(v => /^es([-_]|$)/i.test(v.language) && !seen.has(v.identifier) && seen.add(v.identifier))
      .sort((a, b) => score(b) - score(a) || a.name.localeCompare(b.name));
  } catch { return []; }
}
